<script setup lang="ts">
import ConsoleDialog from './ConsoleDialog.vue'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import {normalizeDecorationLink,decorationLinkLabel,decorationLinkDetail} from '../../../../api/src/core/decoration-links.mjs'
import type {DecorationRoute,DecorationLink} from '../../../../api/src/core/decoration-types'
const props=withDefaults(defineProps<{options:DecorationRoute[];disabled?:boolean;allowEmpty?:boolean;label?:string}>(),{allowEmpty:true,label:'跳转页面'})
const value=defineModel<DecorationLink>({default:''}),open=ref(false),search=ref(''),section=ref('system'),otherOpen=ref(false),draft=ref(''),error=ref('')
const custom=reactive({label:'',url:''}),mini=reactive({appId:'',path:''}),phone=ref('')
const categories=[{key:'system',label:'系统页面',icon:'i-lucide-file-text'},{key:'url',label:'自定义链接',icon:'i-lucide-link'},{key:'mini',label:'其他小程序',icon:'i-lucide-smartphone'},{key:'phone',label:'拨打电话',icon:'i-lucide-phone'}]
const routeSource=(route:DecorationRoute)=>route.source||(route.group==='基础页面'||route.group==='系统自带'?'system':'application')
const applicationRoutes=computed(()=>props.options.filter(route=>routeSource(route)==='application'))
const applicationLabel=computed(()=>applicationRoutes.value[0]?.group||'当前应用')
const pageSection=computed(()=>section.value==='system'||section.value==='application')
const sectionTitle=computed(()=>section.value==='application'?applicationLabel.value:categories.find(c=>c.key===section.value)?.label||'系统页面')
const filtered=computed(()=>props.options.filter(p=>routeSource(p)===section.value&&(!search.value.trim()||(p.label+' '+p.path).toLowerCase().includes(search.value.trim().toLowerCase()))))
const candidate=computed<DecorationLink>(()=>pageSection.value?draft.value:section.value==='url'?{type:'url',...custom}:section.value==='mini'?{type:'mini',...mini}:{type:'phone',number:phone.value})
function chooseSection(value:string){section.value=value;otherOpen.value=['url','mini','phone'].includes(value)}
function show(){if(props.disabled)return;const v=value.value;draft.value=typeof v==='string'?v:'';section.value=typeof v==='string'?routeSource(props.options.find(p=>p.key===v)||{group:'系统自带'} as DecorationRoute):v.type;custom.label=typeof v==='object'&&v.type==='url'?v.label:'';custom.url=typeof v==='object'&&v.type==='url'?v.url:'';mini.appId=typeof v==='object'&&v.type==='mini'?v.appId:'';mini.path=typeof v==='object'&&v.type==='mini'?v.path:'';phone.value=typeof v==='object'&&v.type==='phone'?v.number:'';search.value='';error.value='';otherOpen.value=['url','mini','phone'].includes(section.value);open.value=true}
function confirm(){if(props.disabled)return;try{const result=normalizeDecorationLink(candidate.value,props.options) as DecorationLink;if(!props.allowEmpty&&!result)throw Error('请选择一个跳转页面');value.value=result;open.value=false}catch(e:any){error.value=e.message}}
watch(section,()=>{error.value='';search.value=''})
</script>
<template><div class="path-picker" :class="{'is-disabled':disabled}"><button type="button" class="path-picker-trigger" :disabled="disabled" :aria-label="label" @click="show"><UIcon name="i-lucide-link"/><span><strong>{{!value?'选择跳转目标':decorationLinkLabel(value,options)}}</strong><small v-if="typeof value==='object'&&decorationLinkDetail(value,options)">{{decorationLinkDetail(value,options)}}</small></span><UIcon name="i-lucide-chevron-right"/></button><UButton v-if="allowEmpty&&value" class="path-picker-clear" icon="i-lucide-x" color="neutral" variant="ghost" aria-label="清除链接" title="清除链接" :disabled="disabled" @click="value=''"/>
 <ConsoleDialog v-model:open="open" title="选择链接" size="picker"><template #body><div class="path-picker-dialog"><nav class="path-picker-categories" aria-label="链接分类"><h3>系统自带</h3><button type="button" :class="{active:section==='system'}" @click="chooseSection('system')">系统页面</button><button type="button" class="path-picker-group" :class="{active:['url','mini','phone'].includes(section)}" :aria-expanded="otherOpen" aria-controls="other-link-categories" @click="otherOpen=!otherOpen"><span>其他页面</span><UIcon name="i-lucide-chevron-down" :class="{expanded:otherOpen}"/></button><div v-if="otherOpen" id="other-link-categories" class="path-picker-submenu"><button v-for="item in categories.filter(item=>item.key!=='system')" :key="item.key" type="button" :class="{active:section===item.key}" @click="chooseSection(item.key)">{{item.label}}</button></div><h3 v-if="applicationRoutes.length" class="application-heading">应用</h3><button type="button" :class="{active:section==='application'}" v-if="applicationRoutes.length" @click="chooseSection('application')">{{applicationLabel}}<span class="category-count">{{applicationRoutes.length}}</span></button></nav><div class="path-picker-main">
 <template v-if="pageSection"><div class="path-picker-heading"><h3>{{sectionTitle}}</h3><span>{{filtered.length}} 个页面</span></div><ConsoleInput v-model="search" placeholder="搜索页面名称或路径" aria-label="搜索页面路径"/><div class="path-picker-options"><button v-for="item in filtered" :key="item.key" type="button" :class="{selected:draft===item.key}" :aria-pressed="draft===item.key" :title="item.path" @click="draft=item.key"><strong>{{item.label}}</strong></button><p v-if="!filtered.length" class="text-center text-sm text-muted py-8">没有匹配的页面</p></div></template>
 <div v-else class="path-picker-form"><template v-if="section==='url'"><h3>自定义链接</h3><label><span>链接名称</span><ConsoleInput v-model="custom.label" :maxlength="30" placeholder="输入链接名称"/></label><label><span>链接地址</span><ConsoleInput v-model="custom.url" :maxlength="2048" placeholder="https://example.com"/></label><p>支持 HTTPS 网页或已注册的站内页面路径。小程序打开网页需在微信后台配置业务域名。</p></template><template v-else-if="section==='mini'"><h3>跳转其他小程序</h3><label><span>小程序 AppID</span><ConsoleInput v-model="mini.appId" :maxlength="18" placeholder="wx 开头的 18 位 AppID"/></label><label><span>页面路径</span><ConsoleInput v-model="mini.path" :maxlength="512" placeholder="如 app/pages/index/index"/></label><p>页面路径可携带参数；留空打开目标小程序首页。</p></template><template v-else><h3>拨打电话</h3><label><span>电话号码</span><ConsoleInput v-model="phone" :maxlength="30" placeholder="手机号或固定电话号码"/></label><p>用户点击后调用手机拨号功能。</p></template></div><p v-if="error" class="path-picker-error" role="alert">{{error}}</p></div></div></template><template #footer><div class="path-picker-footer"><div class="path-picker-selection"><span>当前选择</span><strong>{{!candidate?'尚未选择':decorationLinkLabel(candidate,options)||'待填写链接'}}</strong><small :title="decorationLinkDetail(candidate,options)">{{decorationLinkDetail(candidate,options)||'尚未设置跳转目标'}}</small></div><div class="flex shrink-0 gap-3"><UButton color="neutral" variant="outline" @click="open=false">取消</UButton><UButton :disabled="disabled||pageSection&&!allowEmpty&&!draft" @click="confirm">确定</UButton></div></div></template></ConsoleDialog>
</div></template>
<style scoped>
