.path-picker-options{display:flex;flex-wrap:wrap;align-content:flex-start;gap:10px}.path-picker-options>button{flex:0 0 auto;min-height:32px;padding:5px 12px;border-radius:3px}.path-picker-options strong{font-size:13px;line-height:20px}.path-picker-options .selected{background:var(--ui-bg)}
.path-picker-group{justify-content:space-between}.path-picker-group>.iconify{font-size:13px;color:var(--ui-text-muted);transition:transform .15s}.path-picker-group>.iconify.expanded{transform:rotate(180deg)}.path-picker-submenu{padding-left:12px}.path-picker-submenu button{font-size:12px}.path-picker-categories{overflow-y:auto}@media(prefers-reduced-motion:reduce){.path-picker-group>.iconify{transition:none}}
.path-picker{gap:0;border:1px solid var(--ui-border);border-radius:8px;background:var(--ui-bg);transition:border-color .15s;min-height:44px;overflow:hidden}.path-picker:focus-within{border-color:var(--ui-primary);box-shadow:0 0 0 2px color-mix(in srgb,var(--ui-primary) 12%,transparent)}.path-picker-trigger{border:0;border-radius:0;padding:11px 12px;min-height:44px;background:transparent}.path-picker-trigger>span:not(.iconify){min-width:0}.path-picker-trigger strong{font-size:13px;line-height:20px}.path-picker-clear{margin:6px 6px 6px 0;width:30px;min-width:30px;align-self:center}.path-picker.is-disabled{background:var(--ui-bg-muted)}</style>
